module freq_divbyodd #(
    parameter NUM_DIV = 5
) (
    input clk,
    input rst_n,
    output reg clk_div
);


	reg [2:0] cnt1, cnt2;
	wire clk_div1, clk_div2;

	assign clk_div1 = (cnt1 < NUM_DIV/2)? 1'b1:1'b0;
	assign clk_div2 = (cnt2 < NUM_DIV/2)? 1'b1:1'b0;

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			cnt1 <= 3'd0;
			cnt2 <= 3'd0;
		end
		else begin
			if(cnt1 >= NUM_DIV-1) cnt1 <= 3'd0; else cnt1 <= cnt1 + 3'd1;

			if(cnt2 >= NUM_DIV-1) cnt2 <= 3'd0; else cnt2 <= cnt2 + 3'd1;
		end
	end

	assign clk_div = clk_div1 | clk_div2;

endmodule
